function isPageLocked() {
  const html = document.documentElement;
  const { overflow, overflowX, overflowY } = getComputedStyle(html);
  const htmlScrolls = /auto|scroll|overlay|hidden|clip/.test(overflow + overflowY + overflowX);
  return /hidden|clip/.test(getComputedStyle(htmlScrolls ? html : document.body).overflowY);
}

function hasOwnScrollLock(doc: Document) {
  return doc.documentElement.style.overflowX === 'hidden';
}

function DialogOpenChangeSpy(props: {
  onOpenChange: (details: { open: boolean; reason: string | null | undefined }) => void;
}) {
  const { onOpenChange } = props;
  const store = useDialogRootContext();
  const floatingRootContext = store.useState('floatingRootContext');

  React.useEffect(() => {
    function handleOpenChange(details: { open: boolean; reason: string | null | undefined }) {
      onOpenChange(details);
    }

    floatingRootContext.context.events.on('openchange', handleOpenChange);
    return () => {
      floatingRootContext.context.events.off('openchange', handleOpenChange);
    };
  }, [floatingRootContext, onOpenChange]);

  return null;
}

function handleOpenChange(details: { open: boolean; reason: string | null | undefined }) {
      onOpenChange(details);
    }

function ContainedTriggerDialog(props: TestDialogProps) {
  const {
    rootProps,
    triggerProps,
    portalProps,
    popupProps,
    omitTrigger = false,
    includeBackdrop = false,
    triggerWrapper = (trigger) => trigger,
  } = props;

  const { children: triggerChildren, ...restTriggerProps } = triggerProps ?? {};
  const { children: popupChildren, ...restPopupProps } = popupProps ?? {};
  const { children: portalChildren, ...restPortalProps } = portalProps ?? {};

  return (
    <Dialog.Root {...rootProps}>
      {!omitTrigger
        ? triggerWrapper(
            <Dialog.Trigger data-testid="trigger" {...restTriggerProps}>
              {triggerChildren ?? 'Open'}
            </Dialog.Trigger>,
          )
        : null}
      <Dialog.Portal {...restPortalProps}>
        {portalChildren ?? (
          <React.Fragment>
            {includeBackdrop ? (
              <Dialog.Backdrop
                data-testid="backdrop"
                style={{ position: 'fixed', zIndex: 10, inset: 0 }}
              />
            ) : null}
            <Dialog.Popup
              data-testid="dialog-popup"
              style={{ position: 'fixed', zIndex: 10 }}
              {...restPopupProps}
            >
              {popupChildren ?? (
                <React.Fragment>
                  <p>Dialog content</p>
                  <Dialog.Close>Close</Dialog.Close>
                </React.Fragment>
              )}
            </Dialog.Popup>
          </React.Fragment>
        )}
      </Dialog.Portal>
    </Dialog.Root>
  );
}

function DetachedTriggerDialog(props: Omit<TestDialogProps, 'omitTrigger'>) {
  const { triggerProps, triggerWrapper = (trigger) => trigger } = props;

  const { children: triggerChildren, ...restTriggerProps } = triggerProps ?? {};
  const dialogHandle = useRefWithInit(() => Dialog.createHandle()).current;

  return (
    <React.Fragment>
      {triggerWrapper(
        <Dialog.Trigger data-testid="trigger" {...restTriggerProps} handle={dialogHandle}>
          {triggerChildren ?? 'Open'}
        </Dialog.Trigger>,
      )}
      <ContainedTriggerDialog
        {...props}
        rootProps={{ ...props.rootProps, handle: dialogHandle }}
        omitTrigger
      />
    </React.Fragment>
  );
}

function MultipleDetachedTriggersDialog(props: Omit<TestDialogProps, 'omitTrigger'>) {
  const { triggerProps, triggerWrapper = (trigger) => trigger } = props;

  const { children: triggerChildren, ...restTriggerProps } = triggerProps ?? {};
  const dialogHandle = useRefWithInit(() => Dialog.createHandle()).current;

  return (
    <React.Fragment>
      {triggerWrapper(
        <Dialog.Trigger data-testid="trigger" {...restTriggerProps} handle={dialogHandle}>
          {triggerChildren ?? 'Open'}
        </Dialog.Trigger>,
      )}
      <Dialog.Trigger data-testid="trigger-2" handle={dialogHandle}>
        Open another
      </Dialog.Trigger>
      <ContainedTriggerDialog
        {...props}
        rootProps={{ ...props.rootProps, handle: dialogHandle }}
        omitTrigger
      />
    </React.Fragment>
  );
}

export function popupConformanceTests(config: PopupTestConfig) {
  const {
    createComponent,
    triggerMouseAction,
    render,
    expectedPopupRole,
    expectedAriaHasPopupValue = expectedPopupRole,
    alwaysMounted: alwaysMountedParam = false,
    combobox = false,
  } = config;

  const alwaysMounted = alwaysMountedParam === 'only-after-open' ? false : alwaysMountedParam;

  const prepareComponent = (props: TestedComponentProps) => {
    return createComponent({
      ...props,
      trigger: {
        'data-testid': 'trigger',
        ...props.trigger,
      },
      popup: {
        'data-testid': 'popup',
        ...props.popup,
      },
    });
  };

  describe('Popup conformance', () => {
    describe('controlled mode', () => {
      it('opens the popup with the `open` prop', async () => {
        const { rerender } = await render(prepareComponent({ root: { open: false } }));
        if (!alwaysMounted) {
          expect(getPopup()).toBe(null);
        } else {
          expect(getPopup()).toBeInaccessible();
        }

        await rerender(prepareComponent({ root: { open: true } }));
        expect(getPopup()).not.toBe(null);
      });
    });

    if (triggerMouseAction === 'click') {
      describe('uncontrolled mode', () => {
        it('opens the popup when clicking on the trigger', async () => {
          const { user } = await render(prepareComponent({}));

          const trigger = getTrigger();
          if (!alwaysMounted) {
            expect(getPopup()).toBe(null);
          } else {
            expect(getPopup()).toBeInaccessible();
          }

          await user.click(trigger);
          await waitFor(() => {
            expect(getPopup()).not.toBe(null);
          });
        });
      });
    }

    if (expectedPopupRole || triggerMouseAction === 'click') {
      describe('ARIA attributes', () => {
        if (expectedPopupRole) {
          it(`has the ${expectedPopupRole} role on the popup`, async () => {
            await render(prepareComponent({ root: { open: true } }));
            const popup = getPopup();
            expect(popup).not.toBe(null);
            expect(popup).toHaveAttribute('role', expectedPopupRole);
          });
        }

        if (triggerMouseAction === 'click') {
          it('has the `aria-controls` attribute on the trigger', async () => {
            await render(prepareComponent({ root: { open: true } }));
            const trigger = getTrigger();
            const popup = getPopup();
            expect(trigger).toHaveAttribute('aria-controls', popup?.id);
          });

          it('has the `aria-expanded` attribute on the trigger when open', async () => {
            const { user } = await render(prepareComponent({}));
            const trigger = getTrigger();
            if (!alwaysMounted) {
              expect(getPopup()).toBe(null);
            } else {
              expect(getPopup()).toBeInaccessible();
            }
            expect(trigger).toHaveAttribute('aria-expanded', 'false');
            await user.click(trigger);
            await waitFor(() => {
              if (combobox) {
                expect(getPopup()).toHaveAttribute('role', 'listbox');
              } else {
                expect(getPopup()).toHaveAttribute('data-open');
              }
            });
            expect(trigger).toHaveAttribute('aria-expanded', 'true');
          });

          if (expectedAriaHasPopupValue) {
            it('has the `aria-haspopup` attribute on the trigger', async () => {
              await render(prepareComponent({ root: { open: true } }));
              const trigger = getTrigger();
              expect(trigger).toHaveAttribute('aria-haspopup', expectedAriaHasPopupValue);
            });
          }

          it('allows a custom `id` prop', async () => {
            await render(prepareComponent({ root: { open: true }, popup: { id: 'TestId' } }));
            const trigger = getTrigger();
            const popup = getPopup();
            expect(trigger.getAttribute('aria-controls')).toBe(popup?.getAttribute('id'));
          });
        }
      });
    }

    describe('animations', () => {
      beforeEach(() => {
        globalThis.BASE_UI_ANIMATIONS_DISABLED = false;
      });

      afterEach(() => {
        globalThis.BASE_UI_ANIMATIONS_DISABLED = true;
      });

      it('removes the popup when there is no exit animation defined', async ({ skip }) => {
        if (isJSDOM) {
          skip();
        }

        const { rerender } = await render(prepareComponent({ root: { open: true } }));

        await waitFor(() => {
          expect(getPopup()).not.toBe(null);
        });

        await rerender(prepareComponent({ root: { open: false } }));
        await waitFor(() => {
          if (!alwaysMounted && alwaysMountedParam !== 'only-after-open') {
            expect(getPopup()).toBe(null);
          } else {
            expect(getPopup()).toBeInaccessible();
          }
        });
      });

      it('removes the popup when the animation finishes', async ({ skip }) => {
        // XXX: revisit after feedback from the team
        skip();

        if (isJSDOM) {
          skip();
        }

        const handleAnimationEnd = vi.fn();
        const animationName = `anim-${randomStringValue()}`;

        function Test(props: { open: boolean }) {
          const style = `
            @keyframes ${animationName} {
              to {
                opacity: 0;
              }
            }

            .animation-test-popup-${animationName}[data-open] {
              opacity: 1;
            }

            .animation-test-popup-${animationName}[data-ending-style] {
              animation: ${animationName} 150ms;
            }
          `;

          return (
            <div>
              {/* eslint-disable-next-line react/no-danger */}
              <style dangerouslySetInnerHTML={{ __html: style }} />
              {prepareComponent({
                root: { open: props.open },
                portal: { keepMounted: true },
                popup: {
                  className: `animation-test-popup-${animationName}`,
                  onAnimationEnd: handleAnimationEnd,
                },
              })}
            </div>
          );
        }

        const { setProps } = await render(<Test open />);
        await setProps({ open: false });

        await waitFor(() => {
          const popup = getPopup();
          expect(popup).not.toBe(null);
          expect(popup).toBeInaccessible();
        });

        await waitFor(() => {
          expect(handleAnimationEnd).toHaveBeenCalledTimes(1);
        });
      });
    });
  });
}

